def transform(grid):
    h, w = len(grid), len(grid[0])
    def rotate(a):
        return [list(row) for row in zip(*a[::-1])]
    clockwise = rotate(grid)
    half_turn = rotate(clockwise)
    counterclockwise = rotate(half_turn)
    return (
        [grid[r] + clockwise[r] for r in range(h)]
        + [counterclockwise[r] + half_turn[r] for r in range(h)]
